        title: 'Twitter Feed Design',
        content: 'Requirements:\n• Post tweets\n• Follow users\n• Home feed (tweets from followed users)\n• Scale: 500M users, 200M daily active\n\nFeed Generation Approaches:\n\nPull (Fan-in on read):\n• Query all followees on feed request\n• Slow for users following many people\n\nPush (Fan-out on write):\n• On tweet, push to all followers\' feeds\n• Fast reads, slow writes for celebrities\n\nHybrid:\n• Push for regular users\n• Pull for celebrities (>1M followers)\n• Best of both worlds',
        codeExample: '// Hybrid feed approach\nclass FeedService {\n  async postTweet(userId, tweet) {\n    await db.saveTweet(tweet);\n    \n    const followerCount = await social.getFollowerCount(userId);\n    \n    if (followerCount < 10000) {\n      // Fan-out for regular users\n      const followers = await social.getFollowers(userId);\n      await Promise.all(\n        followers.map(f => \n          feedCache.prepend(`feed:${f}`, tweet.id)\n        )\n      );\n    } else {\n      // Celebrity - don\'t fan out, will be pulled\n      await db.markAsCelebrity(userId);\n    }\n  }\n  \n  async getFeed(userId) {\n    // Get cached feed\n    let feed = await feedCache.get(`feed:${userId}`);\n    \n    // Merge in celebrity tweets\n    const celebrities = await social.getFollowedCelebrities(userId);\n    const celebTweets = await db.getRecentTweets(celebrities);\n    \n    return mergeSorted(feed, celebTweets).slice(0, 100);\n  }\n}',
